
(function(){'use strict';
 var guides=[{"src":"demo/workflow/step-01.svg","image":"data:image/svg+xml;base64,","alt":"孔眼图像智能识别 合成图像输入指导图","input":"32×24合成灰度图","output":"输入图像与独立评价参考","observe":"图像进入特征计算，参考掩码不能进入预测特征。","caption":"流程指导示意，不是当前计算结果。先按图梳理输入与产出，再在交互实验对应步骤核对真实计算。"},{"src":"demo/workflow/step-02.svg","image":"data:image/svg+xml;base64,","alt":"孔眼图像智能识别 提取邻域特征指导图","input":"像素及5×5邻域","output":"按训练统计缩放的特征","observe":"从像素到特征逐项追踪，不要把参考标签当特征。","caption":"流程指导示意，不是当前计算结果。先按图梳理输入与产出，再在交互实验对应步骤核对真实计算。"},{"src":"demo/workflow/step-03.svg","image":"data:image/svg+xml;base64,","alt":"孔眼图像智能识别 拟合像素分类器指导图","input":"24幅训练图及像素标签","output":"像素前景打分模型","observe":"按图划分24训练、6验证、6测试，避免同图像素跨集合泄漏。","caption":"流程指导示意，不是当前计算结果。先按图梳理输入与产出，再在交互实验对应步骤核对真实计算。"},{"src":"demo/workflow/step-04.svg","image":"data:image/svg+xml;base64,","alt":"孔眼图像智能识别 计算前景概率指导图","input":"当前像素的邻域特征","output":"每个像素的前景得分图","observe":"看前景与背景边界，得分未经校准，不是工程成功概率。","caption":"流程指导示意，不是当前计算结果。先按图梳理输入与产出，再在交互实验对应步骤核对真实计算。"},{"src":"demo/workflow/step-05.svg","image":"data:image/svg+xml;base64,","alt":"孔眼图像智能识别 生成与清理掩码指导图","input":"前景得分图与阈值","output":"保留目标区域的掩码","observe":"提高阈值或面积门槛会删掉区域，也可能漏掉真实小目标。","caption":"流程指导示意，不是当前计算结果。先按图梳理输入与产出，再在交互实验对应步骤核对真实计算。"},{"src":"demo/workflow/step-06.svg","image":"data:image/svg+xml;base64,","alt":"孔眼图像智能识别 轮廓与质量评价指导图","input":"预测掩码与参考掩码","output":"IoU、Dice、误检与漏检","observe":"用错误位置解释指标，合成图像高分不等于真实场景有效。","caption":"流程指导示意，不是当前计算结果。先按图梳理输入与产出，再在交互实验对应步骤核对真实计算。"}], style=document.createElement('style');style.textContent="/* Step-specific reading guides, shared by the portal and standalone packages. */\n.workflow-guide{margin:16px 0 10px;padding:15px;background:#f7fafb;border:1px solid #dce5e8;border-radius:12px;min-width:0;color:#293b3b}\n.pipeline>.pstep{grid-template-columns:46px minmax(0,1fr)}.pstep .pc{min-width:0}\n.wg-head{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:7px;margin-bottom:10px}\n.wg-head b{font-size:15px;color:#1c6252}.wg-head>span{font-size:12px;color:#64777d}\n.wg-image-scroll{overflow-x:auto;border-radius:8px;background:#fff;max-width:100%}\n.wg-image-scroll:focus-visible{outline:2px solid #4267a8;outline-offset:3px}\n.wg-image-scroll>img{display:block;width:100%;height:auto;max-width:1100px;margin:0 auto;background:#fff;border:0;border-radius:8px}\n.wg-reading{display:grid;grid-template-columns:1fr 1fr 1.35fr;gap:12px;margin-top:12px}\n.wg-reading p{display:flex;flex-direction:column;gap:4px;margin:0!important;font-size:14px!important;line-height:1.7!important;min-width:0}\n.wg-reading b{font-size:12px;color:#4267a8}.wg-reading span{color:#435b5f;overflow-wrap:anywhere}\n.workflow-guide .wg-note{font-size:11px!important;line-height:1.6!important;color:#69797e;margin:10px 0 0!important}\n.workflow-guide[data-guide-step]{margin-bottom:22px}.workflow-guide+.formula{margin-top:12px}\n@media(max-width:700px){.workflow-guide{padding:10px;margin:12px 0}.pipeline>.pstep{grid-template-columns:38px minmax(0,1fr)}.wg-reading{grid-template-columns:1fr;gap:8px}.wg-reading p{display:grid;grid-template-columns:58px minmax(0,1fr);gap:8px;font-size:13px!important}.wg-reading b{padding-top:2px}.wg-head>span{font-size:11px}.pstep .pc{padding:12px 10px}.wg-image-scroll>img{min-width:720px;border-radius:5px}}\n";document.head.appendChild(style);
 function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
 var panel=document.getElementById('step-panel');if(!panel)return;
 var queued=false;
 function paint(){queued=false;var active=document.querySelector('[data-step][aria-selected="true"]');var i=active?Number(active.getAttribute('data-step')):0;var g=guides[i];if(!g)return;var old=panel.querySelector('.workflow-guide');if(old&&old.getAttribute('data-guide-step')===String(i))return;if(old)old.remove();
  var f=document.createElement('figure');f.className='workflow-guide';f.setAttribute('data-guide-step',String(i));f.setAttribute('aria-label',g.alt);
  f.innerHTML='<div class="wg-head"><b>第 '+('0'+(i+1)).slice(-2)+' 步指导图</b><span>下方图表展示当前真实计算</span></div><div class="wg-image-scroll" tabindex="0" aria-label="指导图，小屏可横向查看"><img width="960" height="340" src="'+esc(g.image)+'" alt="'+esc(g.alt)+'"></div><figcaption class="wg-reading"><p><b>输入</b><span>'+esc(g.input)+'</span></p><p><b>产出</b><span>'+esc(g.output)+'</span></p><p><b>观察重点</b><span>'+esc(g.observe)+'</span></p></figcaption><p class="wg-note">'+esc(g.caption)+'</p>';panel.insertBefore(f,panel.firstChild);
 }
 function schedule(){if(!queued){queued=true;requestAnimationFrame(paint);}}
 new MutationObserver(schedule).observe(panel,{childList:true});paint();
})();
